const people=['RA','ZS','JH','MH','CF','MM','PH','JP','JC','DA'];const colors=['#74C8FF','#FF8C00','#FF3B30','#1E6B3A','#8B45E8','#B6E82E','#1A3F9C','#FF7F6A','#FFE135','#FF5CA8'];const inks=['#120d20','#120d20','#120d20','#F4FFF7','#F7F3FF','#120d20','#F3F7FF','#120d20','#120d20','#120d20'];const colorNames=['Light Blue','Orange','Red','Forest Green','Purple','Lime Green','Dark Blue','Coral / Salmon','Yellow','Pink'];const players=document.querySelector('#players');if(!players.querySelector('.player'))people.forEach((name,i)=>{const b=document.createElement('button');b.className='player';b.style.setProperty('--color',colors[i]);b.style.setProperty('--ink',inks[i]);b.dataset.player=name;b.setAttribute('aria-label',name+(i===0?', birthday player':', player '+(i+1)));b.innerHTML=`<span class="number">P${i+1}</span><span class="initial">${name}</span>`;const slot=document.createElement("div");slot.className="player-slot";slot.append(b);if(i===0){const label=document.createElement("span");label.className="birthday-tag";label.textContent="BIRTHDAY PLAYER";b.append(label)}players.append(slot)});const dates=document.querySelector('#dates');if(!dates.querySelector('button'))for(let i=1;i<=30;i++){let b=document.createElement('button');b.textContent=i;b.setAttribute('aria-label',`November ${i}, 2026`);if(i>=20&&i<=22)b.className='weekend';dates.append(b)}dates.querySelectorAll('button').forEach(b=>{const i=Number(b.textContent);b.onclick=()=>{if(i>=20&&i<=22)showDay(['friday','saturday','sunday'][i-20]);else{document.querySelector('#day-note').hidden=false;document.querySelector('#day-note').textContent='The birthday weekend is November 20–22.'}}});
const contents={tldr:["TL / DR","<div class=\"tldr\"><section><h3>Friday, Nov 20</h3><ul><li><span>4:00 PM</span>Check in at the Airbnb near Wall Street.</li><li><span>8:00 PM</span>Magic Hour Rooftop Ice Bar in Times Square. The theme is synthwave.</li><li><span>AFTER</span>Pieces Bar and The Stonewall Inn in the West Village. The plan is still open.</li></ul></section><section><h3>Saturday, Nov 21</h3><ul><li><span>MORNING</span>Stranger No Danger, in pairs through noon: RA &amp; CF, JC &amp; DA, MM &amp; JH, ZS &amp; PH.</li><li><span>AFTERNOON</span>Art, cocktails, and roaming. Brooklyn is optional: water taxi, Artists &amp; Fleas, Bushwick Country Club, Brooklyn Brewery.</li><li><span>EVENING</span>Speakeasy crawl is optional. Be at the Airbnb by 5 or 6 PM if you are joining.</li></ul></section><section><h3>Sunday, Nov 22</h3><p>Escape from NY.</p></section><section><h3>Any time</h3><p>Take nine pictures in your assigned color.</p></section></div>"],burritos:["BURRITOS","<ul class=\"restaurant-list\"><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Electric+Burrito%2C+81+St.+Marks+Pl%2C+East+Village%2C+Manhattan%2C+New+York\" target=\"_blank\" rel=\"noopener\">Electric Burrito</a> <span>(East Village, Manhattan)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: Carne asada California burrito</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Los+Burritos+Juarez%2C+354+Myrtle+Ave%2C+Fort+Greene%2C+Brooklyn%2C+New+York\" target=\"_blank\" rel=\"noopener\">Los Burritos Juarez</a> <span>(Fort Greene, Brooklyn)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: Colorado or bean &amp; cheese</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Vato%2C+226+7th+Ave%2C+Park+Slope%2C+Brooklyn%2C+New+York\" target=\"_blank\" rel=\"noopener\">Vato</a> <span>(Park Slope, Brooklyn)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: Bean &amp; cheese or pork verde</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Son+del+North%2C+177+Orchard+St%2C+Lower+East+Side%2C+Manhattan%2C+New+York\" target=\"_blank\" rel=\"noopener\">Son del North</a> <span>(Lower East Side, Manhattan)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: Carne asada or bean &amp; cheese</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=B%E2%80%99KLYN+BURRO%2C+922+Fulton+St%2C+Clinton+Hill%2C+Brooklyn%2C+New+York\" target=\"_blank\" rel=\"noopener\">B\u2019KLYN BURRO</a> <span>(Clinton Hill, Brooklyn)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: C. Hill Rey / chile relleno</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Taqueria+Tlaxcalli%2C+2103+Starling+Ave%2C+Parkchester%2C+The+Bronx%2C+New+York\" target=\"_blank\" rel=\"noopener\">Taqueria Tlaxcalli</a> <span>(Parkchester, The Bronx)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: Steak burrito</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=La+Abuelita%2C+123+Wyckoff+Ave%2C+Bushwick%2C+Brooklyn%2C+New+York\" target=\"_blank\" rel=\"noopener\">La Abuelita</a> <span>(Bushwick, Brooklyn)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: Carne asada or al pastor</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Plaza+Ortega%2C+140+Stanhope+St%2C+Bushwick%2C+Brooklyn%2C+New+York\" target=\"_blank\" rel=\"noopener\">Plaza Ortega</a> <span>(Bushwick, Brooklyn)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: Sonora Burrito</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Summer+Salt%2C+30+E+23rd+St%2C+Flatiron%2C+Manhattan%2C+New+York\" target=\"_blank\" rel=\"noopener\">Summer Salt</a> <span>(Flatiron, Manhattan)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: Baja crispy fish, California style</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Super+Burrito%2C+1-90+Beach+69th+St%2C+Rockaway+Beach%2C+Queens%2C+New+York\" target=\"_blank\" rel=\"noopener\">Super Burrito</a> <span>(Rockaway Beach, Queens)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: California or Mission \u201cSuper\u201d</span></li></ul>"],speakeasies:["SPEAKEASIES","<ul class=\"restaurant-list\"><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Please+Don%E2%80%99t+Tell%2C+%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">Please Don\u2019t Tell</a> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Entrance: Phone booth</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Bathtub+Gin%2C+%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">Bathtub Gin</a> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Entrance: Coffee shop</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=The+Little+Shop%2C+%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">The Little Shop</a> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Entrance: Bodega</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Nothing+Really+Matters%2C+%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">Nothing Really Matters</a> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Entrance: Subway entrance</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=The+Back+Room%2C+%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">The Back Room</a> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Entrance: Alley entrance</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Patent+Pending%2C+%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">Patent Pending</a> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Entrance: Hidden caf\u00e9</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Little+Branch%2C+%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">Little Branch</a> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Entrance: Unmarked door</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=The+Woo+Woo%2C+%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">The Woo Woo</a> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Entrance: Secret stairway</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Fig.+19%2C+%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">Fig. 19</a> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Entrance: Gallery door</span></li></ul>"],pizza:["PIZZA","<ul class=\"restaurant-list\"><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=L%E2%80%99Industrie%2C+Williamsburg%2C+Brooklyn%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">L\u2019Industrie</a> <span>(Williamsburg, Brooklyn)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: Thin, crispy, and flavorful. A must-try slice in NYC!</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Una+Pizza+Napoletana%2C+Lower+East+Side%2C+Manhattan%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">Una Pizza Napoletana</a> <span>(Lower East Side, Manhattan)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: World-class Neapolitan pizza with perfectly chewy crust.</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Lucali%2C+Carroll+Gardens%2C+Brooklyn%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">Lucali</a> <span>(Carroll Gardens, Brooklyn)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: Famous for its thin, wood-fired whole pies. A true NYC classic.</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Scarr%E2%80%99s+Pizza%2C+Lower+East+Side%2C+Manhattan%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">Scarr\u2019s Pizza</a> <span>(Lower East Side, Manhattan)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: Iconic NYC slice with a crispy, flavorful crust.</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Mama%E2%80%99s+TOO%21%2C+West+Village%2C+Manhattan%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">Mama\u2019s TOO!</a> <span>(West Village, Manhattan)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: Famous for thick, crispy-bottomed square slices.</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=John%E2%80%99s+of+Bleecker+Street%2C+Greenwich+Village%2C+Manhattan%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">John\u2019s of Bleecker Street</a> <span>(Greenwich Village, Manhattan)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: Historic coal-fired pizza since 1929.</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Prince+Street+Pizza%2C+Nolita%2C+Manhattan%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">Prince Street Pizza</a> <span>(Nolita, Manhattan)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: Legendary spicy squares. Try the Hotbox slice!</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Joe%E2%80%99s+Pizza%2C+Greenwich+Village%2C+Manhattan%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">Joe\u2019s Pizza</a> <span>(Greenwich Village, Manhattan)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: The quintessential NYC slice. Simple, cheesy, and perfect.</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Rubirosa%2C+Nolita%2C+Manhattan%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">Rubirosa</a> <span>(Nolita, Manhattan)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: Thin crust with rich, flavorful toppings.</span></li><li><a href=\"https://www.google.com/maps/search/?api=1&amp;query=Emmy+Squared%2C+Williamsburg%2C+Brooklyn%2C+New+York+City\" target=\"_blank\" rel=\"noopener\">Emmy Squared</a> <span>(Williamsburg, Brooklyn)</span> <span class=\"rec-divider\" aria-hidden=\"true\">\u2022</span> <span>Rec: Modern Detroit-style pizza with creative flavors.</span></li></ul>"],home:['AIRBNB / HOME BASE',`<div class="stay"><h3 class="split stay-when">FRIDAY CHECK-IN: 4:00 PM</h3><p class="stay-offer"><a href="https://www.airbnb.com/rooms/1521902811635943582" target="_blank" rel="noopener">Airbnb listing</a></p><p class="stay-address"><a href="https://www.google.com/maps/search/?api=1&amp;query=110+Wall+Street%2C+New+York%2C+NY+10005%2C+United+States" target="_blank" rel="noopener">110 Wall Street, New York, NY 10005, United States</a></p><p class="stay-rooms">Four bedrooms, four queen beds, a couch, and an air mattress.</p><p class="stay-price"><span class="rec-divider" aria-hidden="true">\u2022</span> $240 per person</p></div>`],dance:['FRIDAY / MAGIC HOUR @ 8:00 PM','<h3>RESERVATION</h3><p><a href="https://www.google.com/maps/search/?api=1&amp;query=Magic+Hour+Rooftop+Bar%2C+485+7th+Ave%2C+Times+Square%2C+Manhattan%2C+New+York" target="_blank" rel="noopener">Magic Hour Rooftop Ice Bar</a> <span>(Times Square, Manhattan)</span></p><h3>AFTERWARDS TBD</h3><p><a href="https://www.google.com/maps/search/?api=1&amp;query=Pieces+Bar%2C+8+Christopher+St%2C+West+Village%2C+Manhattan%2C+New+York" target="_blank" rel="noopener">Pieces Bar</a> <span>(West Village, Manhattan)</span></p><p><a href="https://www.google.com/maps/search/?api=1&amp;query=The+Stonewall+Inn%2C+53+Christopher+St%2C+West+Village%2C+Manhattan%2C+New+York" target="_blank" rel="noopener">The Stonewall Inn</a> <span>(West Village, Manhattan)</span></p>'],hunt:['SATURDAY PLANS / ALL DAY','<p>A day dedicated to art, cocktails, and exploring together.</p><h3 class="split">MORNING-NOON</h3><p>Stranger No Danger</p><h3 class="split">LATE AFTERNOON TO EARLY EVENING OPTIONALS</h3><p><a href="https://www.google.com/maps/search/?api=1&amp;query=NYC+Ferry+Wall+Street+Pier+11%2C+Manhattan%2C+New+York" target="_blank" rel="noopener">Water Taxi to Brooklyn</a></p><p><a href="https://www.google.com/maps/search/?api=1&amp;query=Artists+%26+Fleas%2C+70+North+7th+Street%2C+Williamsburg%2C+Brooklyn%2C+New+York" target="_blank" rel="noopener">Artists &amp; Fleas</a></p><p><a href="https://www.google.com/maps/search/?api=1&amp;query=Bushwick+Country+Club%2C+608+Grand+Street%2C+Brooklyn%2C+New+York" target="_blank" rel="noopener">Bushwick Country Club</a></p><p><a href="https://www.google.com/maps/search/?api=1&amp;query=Brooklyn+Brewery%2C+1+Wythe+Avenue%2C+Williamsburg%2C+Brooklyn%2C+New+York" target="_blank" rel="noopener">Brooklyn Brewery</a></p><p>Hit up one or two more Brooklyn bars</p><h3 class="split">EVENING OPTIONALS</h3><p>Head back for Speakeasy Crawl. Be at the AirBnB by 5 or 6 PM</p>'],music:['COLOR PHOTO HUNT','<h3 class="split">ANY TIME</h3><ol><li>Select your character to view your color.</li><li>Take nine pictures featuring your color.</li><li>RA will assemble your photos into a souvenir print.</li></ol><p>Text RA your photos after the weekend ends.</p>'],bond:['SAT AM / STRANGER NO DANGER','<p>Bonding time, morning through noon, or however long you want.</p><h3 class="split">PAIRS</h3><p class="stack-list"><span class="stack-item">RA &amp; CF</span> <span class="rec-divider" aria-hidden="true">\u2022</span> <span class="stack-item">JC &amp; DA</span> <span class="rec-divider" aria-hidden="true">\u2022</span> <span class="stack-item">MM &amp; JH</span> <span class="rec-divider" aria-hidden="true">\u2022</span> <span class="stack-item">ZS &amp; PH</span></p><h3 class="split">IDEAS</h3><p class="stack-list"><span class="stack-item">Holiday Market</span> <span class="rec-divider" aria-hidden="true">\u2022</span> <span class="stack-item">Bagel Shop</span> <span class="rec-divider" aria-hidden="true">\u2022</span> <span class="stack-item">Coffee</span> <span class="rec-divider" aria-hidden="true">\u2022</span> <span class="stack-item">Chelsea Market</span> <span class="rec-divider" aria-hidden="true">\u2022</span> <span class="stack-item">Brunch</span> <span class="rec-divider" aria-hidden="true">\u2022</span> <span class="stack-item">Something touristy</span></p>'],synth:['FRI PM / SYNTHWAVE','<p>The theme is synthwave. Bring the retro-future energy.</p><h3 class="split">8PM RESERVATION</h3><p><a href="https://www.google.com/maps/search/?api=1&amp;query=Magic+Hour+Rooftop+Bar%2C+485+7th+Ave%2C+Times+Square%2C+Manhattan%2C+New+York" target="_blank" rel="noopener">Magic Hour Rooftop Ice Bar</a></p><h3 class="split">AFTERWARDS TBD</h3><p><a href="https://www.google.com/maps/search/?api=1&amp;query=Pieces+Bar%2C+8+Christopher+St%2C+West+Village%2C+Manhattan%2C+New+York" target="_blank" rel="noopener">Pieces Bar</a></p><p><a href="https://www.google.com/maps/search/?api=1&amp;query=The+Stonewall+Inn%2C+53+Christopher+St%2C+West+Village%2C+Manhattan%2C+New+York" target="_blank" rel="noopener">The Stonewall Inn</a></p>'],speakeasy:['SAT PM / OPTIONALS','<p>After morning bonding, feel free to meet up for any of the following:</p><h3 class="split">LATE AFTERNOON TO EARLY EVENING OPTIONALS</h3><p><a href="https://www.google.com/maps/search/?api=1&amp;query=NYC+Ferry+Wall+Street+Pier+11%2C+Manhattan%2C+New+York" target="_blank" rel="noopener">Water Taxi to Brooklyn</a></p><p><a href="https://www.google.com/maps/search/?api=1&amp;query=Artists+%26+Fleas%2C+70+North+7th+Street%2C+Williamsburg%2C+Brooklyn%2C+New+York" target="_blank" rel="noopener">Artists &amp; Fleas</a></p><p><a href="https://www.google.com/maps/search/?api=1&amp;query=Bushwick+Country+Club%2C+608+Grand+Street%2C+Brooklyn%2C+New+York" target="_blank" rel="noopener">Bushwick Country Club</a></p><p><a href="https://www.google.com/maps/search/?api=1&amp;query=Brooklyn+Brewery%2C+1+Wythe+Avenue%2C+Williamsburg%2C+Brooklyn%2C+New+York" target="_blank" rel="noopener">Brooklyn Brewery</a></p><p>Hit up one or two more Brooklyn bars</p><h3 class="split">EVENING OPTIONALS</h3><p>Head back for Speakeasy Crawl. Be at the AirBnB by 5 or 6 PM</p>']};const dialog=document.querySelector('dialog');function modal(title,body){document.querySelector('#modal-body').innerHTML='<h2>'+title+'</h2>'+body;dialog.showModal();dialog.focus({preventScroll:true})}document.addEventListener('click',async e=>{const p=e.target.closest('[data-player]');if(p){document.querySelectorAll('.player').forEach(x=>x.classList.toggle('selected',x.dataset.player===p.dataset.player));const n=p.dataset.player;document.querySelector('#selection').textContent='10 FRIENDS + MUNROE';modal(n==='RA'?'RA / LEVEL 44':n,n==='MUNROE'?`<p>Our four-legged companion. She's such a good girl.</p><img class="munroe-modal-portrait" src="assets/munroe-portrait.svg" alt="Pixel portrait of Munroe, a tan and cream Australian shepherd">`:`${n==='RA'?'<p>The birthday player and weekend planner.</p>':''}<p>Photo-hunt color: ${colorNames[people.indexOf(n)]}.</p><ol><li>Take nine pictures featuring your color.</li><li>RA will assemble your photos into a souvenir print.</li></ol><div class="palette" style="--color:${colors[people.indexOf(n)]}"></div>`)}const a=e.target.closest('[data-modal]');if(a){modal(...contents[a.dataset.modal])}const t=e.target.closest('[data-tab]');if(t)showDay(t.dataset.tab)});document.querySelector('#close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>document.querySelectorAll('.player.selected').forEach(x=>x.classList.remove('selected')));dialog.addEventListener('click',e=>{if(e.target===dialog){let r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});function showDay(day){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===day));const note=document.querySelector('#day-note');const text={friday:'<span class="day-prefix">FRIDAY 20 / </span>4 PM check-in · 8 PM Magic Hour Icebar · Various locations in the Stonewall/Christopher St. area.',saturday:'<span class="day-prefix">SATURDAY 21 / </span>Stranger No Danger · Art, cocktails & free roam · Speakeasy crawl',sunday:'<span class="day-prefix">SUNDAY 22 / </span>Escape from NY'};note.hidden=!text[day];note.innerHTML=text[day]||'';if(day==='crew')document.querySelector('#crew').scrollIntoView({block:'nearest'});if(day==='quests')document.querySelector('#quests').scrollIntoView({block:'nearest'});}

const radio=document.querySelector('#plaza-radio'),radioPlay=document.querySelector('#radio-play'),radioStop=document.querySelector('#radio-stop'),radioStatus=document.querySelector('#radio-status');
const playIcon='<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M5 2v16l13-8z"/></svg>',pauseIcon='<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3 2h5v16H3zM12 2h5v16h-5z"/></svg>';
function radioState(playing){radioPlay.innerHTML=playing?pauseIcon:playIcon;radioPlay.setAttribute('aria-label',playing?'Pause Plaza Radio':'Play Plaza Radio');radioPlay.setAttribute('aria-pressed',String(playing))}
radioPlay.addEventListener('click',async()=>{if(!radio.paused){radio.pause();return}radioStatus.textContent='CONNECTING';try{await radio.play()}catch{radioStatus.textContent='UNAVAILABLE';radioState(false)}});
radioStop.addEventListener('click',()=>{radio.pause();radio.load();radioState(false);radioStatus.textContent=''});
radio.addEventListener('playing',()=>{radioState(true);radioStatus.textContent='LIVE'});radio.addEventListener('pause',()=>{radioState(false);radioStatus.textContent='PAUSED'});radio.addEventListener('error',()=>{radioState(false);radioStatus.textContent='UNAVAILABLE'});

// Move the same player so playback survives responsive layout changes.
const musicPlayer=document.querySelector('.radio-player'),desktopMusicSlot=document.querySelector('.system'),mobileMusicSlot=document.querySelector('.crew-heading'),mobileMusicQuery=window.matchMedia('(max-width:960px)');
function placeMusicPlayer(){if(mobileMusicQuery.matches)mobileMusicSlot.append(musicPlayer);else desktopMusicSlot.insertBefore(musicPlayer,desktopMusicSlot.lastElementChild)}
mobileMusicQuery.addEventListener('change',placeMusicPlayer);placeMusicPlayer();
const stage=document.querySelector('.console');
function revealStage(){stage.classList.add('is-ready');setTimeout(()=>stage.classList.add('is-settled'),200)}
const fontReady=document.fonts&&document.fonts.ready?document.fonts.ready.catch(()=>{}):Promise.resolve();
Promise.race([fontReady,new Promise(resolve=>setTimeout(resolve,800))]).then(revealStage);

document.querySelectorAll('.nearby-buttons button, .home .expand').forEach(button=>{
  let releaseTimer=0;
  const release=()=>{clearTimeout(releaseTimer);releaseTimer=setTimeout(()=>button.classList.remove('pressed'),420)};
  button.addEventListener('pointerdown',()=>{clearTimeout(releaseTimer);button.classList.add('pressed')});
  button.addEventListener('pointerup',release);
  button.addEventListener('pointercancel',release);
});
const fartTracks=['assets/farts/00.mp3','assets/farts/01.mp3','assets/farts/02.mp3','assets/farts/03.mp3','assets/farts/04.mp3','assets/farts/05.mp3','assets/farts/06.mp3','assets/farts/07.mp3','assets/farts/08.mp3','assets/farts/09.mp3','assets/farts/10.mp3'];
const fartAudio=new Audio();
let fartIndex=0;
document.querySelector('#heart-fart').addEventListener('click',()=>{const src=fartTracks[fartIndex];fartIndex=(fartIndex+1)%fartTracks.length;fartAudio.pause();fartAudio.src=src;fartAudio.play()});

// On 2- and 3-across, the fins splay away from the logo with scroll position
// and return as that position comes back. The travel matches the header
// leaving the screen, so the motion reads while the fins are still visible.
const brand=document.querySelector('.brand');
const finSpreadQuery=window.matchMedia('(max-width:680px)');
const finMotionQuery=window.matchMedia('(prefers-reduced-motion: reduce)');
const finSpreadDistance=170;
const finSpreadMax=22;
let finSpreadFrame=0;
function updateFinSpread(){
  finSpreadFrame=0;
  if(!brand)return;
  if(!finSpreadQuery.matches||finMotionQuery.matches){
    brand.style.removeProperty('--fin-spread');
    return;
  }
  const progress=Math.min(1,Math.max(0,window.scrollY/finSpreadDistance));
  brand.style.setProperty('--fin-spread',(progress*finSpreadMax).toFixed(2)+'deg');
}
function requestFinSpread(){
  if(!finSpreadFrame)finSpreadFrame=requestAnimationFrame(updateFinSpread);
}
finSpreadQuery.addEventListener('change',updateFinSpread);
finMotionQuery.addEventListener('change',updateFinSpread);
window.addEventListener('scroll',requestFinSpread,{passive:true});
updateFinSpread();

const confettiCanvas=document.createElement('canvas');
confettiCanvas.setAttribute('aria-hidden','true');
confettiCanvas.style.cssText='position:fixed;inset:0;width:100%;height:100%;pointer-events:none;z-index:40';
document.body.append(confettiCanvas);
const confettiCtx=confettiCanvas.getContext('2d');
const confettiColors=['#ff4ad2','#ff5ca8','#ffe135','#67f6ff','#ff7f6a','#f7f3ff','#b6e82e'];
let confettiPieces=[];
let confettiFrame=0;
function sizeConfetti(){
  const dpr=Math.min(window.devicePixelRatio||1,2);
  confettiCanvas.width=innerWidth*dpr;
  confettiCanvas.height=innerHeight*dpr;
  confettiCtx.setTransform(dpr,0,0,dpr,0,0);
}
document.querySelector('.cable-dot').addEventListener('click',event=>{event.stopPropagation();burstConfetti(event.currentTarget)});
sizeConfetti();
window.addEventListener('resize',sizeConfetti);
function burstConfetti(button){
  if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  const rect=button.getBoundingClientRect();
  const x=rect.left+rect.width/2;
  const y=rect.top+rect.height/2;
  for(let i=0;i<72;i++){
    const angle=Math.random()*Math.PI*2;
    const speed=3.5+Math.random()*7;
    confettiPieces.push({
      x,y,
      vx:Math.cos(angle)*speed,
      vy:Math.sin(angle)*speed-2.5,
      g:.16+Math.random()*.1,
      w:6+Math.random()*6,
      h:3+Math.random()*4,
      color:confettiColors[i%confettiColors.length],
      rot:Math.random()*Math.PI,
      spin:(Math.random()-.5)*.28,
      life:1
    });
  }
  if(confettiPieces.length>220)confettiPieces=confettiPieces.slice(-220);
  if(!confettiFrame)confettiFrame=requestAnimationFrame(drawConfetti);
}
function drawConfetti(){
  confettiCtx.clearRect(0,0,innerWidth,innerHeight);
  confettiPieces=confettiPieces.filter(piece=>piece.life>0&&piece.y<innerHeight+24);
  for(const piece of confettiPieces){
    piece.vy+=piece.g;
    piece.x+=piece.vx;
    piece.y+=piece.vy;
    piece.vx*=.99;
    piece.rot+=piece.spin;
    piece.life-=.012;
    confettiCtx.save();
    confettiCtx.translate(piece.x,piece.y);
    confettiCtx.rotate(piece.rot);
    confettiCtx.globalAlpha=Math.max(0,piece.life);
    confettiCtx.fillStyle=piece.color;
    confettiCtx.fillRect(-piece.w/2,-piece.h/2,piece.w,piece.h);
    confettiCtx.restore();
  }
  if(confettiPieces.length)confettiFrame=requestAnimationFrame(drawConfetti);
  else{confettiFrame=0;confettiCtx.clearRect(0,0,innerWidth,innerHeight)}
}
